const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
 ['入會一定要有人介紹嗎','沒有規定入會一定要有人介紹'],['加入協會要不要有人推薦','沒有規定入會一定要有人介紹'],
 ['入會費跟常年會費是同一個嗎','不是同一個'],['入會費和常年會費是不是一樣','不是同一個'],
 ['退會之後入會費可以退嗎','退費原則'],['會員退出已繳的會費能拿回來嗎','退費原則'],
 ['會員人數變動要報備嗎','不用逐次報備'],['新增會員要通知縣府嗎','不用逐次報備'],
 ['會員有什麼權利','表決權'],['會員有哪些權益','表決權'],
 ['會員有什麼義務','章程'],['會員的義務有哪些','章程'],
 ['會員不出席開會會怎樣','沒有規定會員沒出席大會要受處罰'],['會員缺席大會有什麼後果','書面委託'],
 ['會員有沒有投票權','每一會員（會員代表）為一權'],['一般會員可以投票嗎','每一會員（會員代表）為一權'],
 ['會員可以查帳嗎','沒有明文規定'],['會員想看財務報表可以嗎','監事會'],
 ['協會可以請專職人員嗎','可以。'],['協會能不能聘專任員工','可以。'],
 ['工作人員薪水誰決定','第7條'],['總幹事的薪資怎麼訂','理事會訂定'],
 ['聘用員工要報備嗎','章程'],['請總幹事要報縣府備查嗎','章程'],
];
const no=['合作社社員不出席開會會怎樣','社區發展協會會員有什麼權利','理事不出席開會會怎樣','贊助會員有沒有投票權','商業公會會員有什麼義務','會員可以委託幾個人投票','員工離職要報備嗎','財務人員可以兼任嗎','會員被質疑挪用公款可以查帳嗎'];
let bad=0;
yes.forEach(([q,e])=>{const a=A(q);const txt=a?(a.title+a.summary+(a.statutes||[]).map(x=>x.title).join('')):'';if(!txt.includes(e)||!a.direct){bad++;console.log('✗',q,a&&a.title)}});
no.forEach(q=>{const a=A(q);if(a&&/(入會一定要有人介紹|入會費和常年會費不是同一個|退會後已繳|會員人數增減|會員的權利：|會員的義務：|會員沒出席大會|會員有投票權|會員可以查帳嗎：|協會可以請專職|工作人員薪水誰決定|聘用員工要不要報備)/.test(a.title)){bad++;console.log('誤觸',q,a.title)}});
console.log(bad?'失敗 '+bad:'全部通過');process.exit(bad?1:0);
